using System.Globalization;using UnityEngine;using UnityEngine.UI;
public sealed partial class TrainingOverlay {
 TrainingCombatComparison combatComparison;GameObject comparisonOptions;InputField[] comparisonFields=new InputField[15],comparisonTimingFields=new InputField[9];Text comparisonStatus;bool syncingComparison;
 public bool OptionComparisonVisible{get;private set;}public InputField[] ComparisonFields=>comparisonFields;public InputField[] ComparisonTimingFields=>comparisonTimingFields;
 void ColorComparisonHurtbox(HurtboxOutline item){if(player!=null&&player.CombatV01!=null&&item.hurtbox!=null){bool v01Selected=item.hurtbox.Fighter.LastContactHurtboxId==item.hurtbox.StableId;item.line.enabled=true;item.line.startColor=item.line.endColor=v01Selected?Color.yellow:item.hurtbox.Fighter==player?Color.green:Color.cyan;return;}if(combatComparison==null||!combatComparison.Ready||item.hurtbox==null)return;var contact=player.opponent.LastResolvedContact;bool selected=contact!=null&&item.hurtbox.Fighter==player.opponent&&item.hurtbox.StableId==contact.partId;item.line.enabled=selected;item.line.startColor=item.line.endColor=selected?Color.yellow:item.hurtbox.Upper?Color.cyan:new Color(.5f,1f,.1f);}
 InputField ComparisonNumber(string name,UnityEngine.Events.UnityAction<string> changed){var go=OptionObject(name,comparisonOptions.transform);go.AddComponent<Image>().color=new Color(.11f,.16f,.18f);var field=go.AddComponent<TrainingOptionInputField>();field.characterLimit=12;field.lineType=InputField.LineType.SingleLine;field.shouldActivateOnSelect=false;var text=OptionText("Text","",go.transform,14);text.rectTransform.anchorMin=Vector2.zero;text.rectTransform.anchorMax=Vector2.one;text.rectTransform.offsetMin=new Vector2(6,2);text.rectTransform.offsetMax=new Vector2(-6,-2);field.textComponent=text;field.onValueChanged.AddListener(changed);return field;}
 void CreateComparisonOptions(){combatComparison=player==null?null:player.GetComponent<TrainingCombatComparison>();if(combatComparison==null||!combatComparison.Ready)return;OptionButton("NavComparison","Combat compare",optionPanel,()=>ShowComparisonOptions(true));comparisonOptions=OptionObject("ComparisonSettings",optionPanel);OptionText("Header","開発用3P比較 | 時間・判定・連係は両式で共通",comparisonOptions.transform,16);
  OptionButton("CompareSubtract","Subtraction / 引き算",comparisonOptions.transform,()=>{combatComparison.SetMode(0);SyncComparison();});OptionButton("CompareAttenuate","Attenuation / 減衰（実験）",comparisonOptions.transform,()=>{combatComparison.SetMode(1);SyncComparison();});
  string[] names={"弱P","中P","強P"};for(int row=0;row<3;row++){int captured=row;OptionText("CompareLabel"+row,names[row]+" | 最弱A / 最強A / 防御倍率 / ヒット境界 / ガードダメージ率",comparisonOptions.transform,12);for(int col=0;col<5;col++){int index=row*5+col;comparisonFields[index]=ComparisonNumber("CompareField"+index,_=>ComparisonEdited(captured));}OptionText("CompareTimeLabel"+row,"",comparisonOptions.transform,12);for(int col=0;col<3;col++){int index=row*3+col;comparisonTimingFields[index]=ComparisonNumber("CompareTimingField"+index,_=>ComparisonTimingEdited(captured));}}
  OptionButton("CompareDefaults","式をSO初期値へ",comparisonOptions.transform,()=>{combatComparison.ResetDraft();SyncComparison();});OptionButton("CompareTimingDefaults","時間を元の技SO値へ",comparisonOptions.transform,()=>{combatComparison.ResetTimings();SyncComparison();});OptionButton("CompareReset","試行リセット",comparisonOptions.transform,()=>combatComparison.ResetTrial());OptionButton("CompareComboProbe","コンボ確認: 防御0",comparisonOptions.transform,()=>{foreach(var entry in combatComparison.Active.moves)entry.defenseMultiplier=0;combatComparison.ResetTrial();SyncComparison();});comparisonStatus=OptionText("CompareStatus","",comparisonOptions.transform,12);
  OptionText("CompareNote","防御倍率: 同じ部位の補正済み防御Dに乗算。境界: 最終結果 > 境界でHit（同値はGuard）。\nガードダメージ率: 元ダメージ×率。0=0%、0.1=10%、1=100%。\n時間は60F=1秒・小数F互換。持続区間[発生, 発生+持続)、硬直は持続終了後の長さ。\n持続0F=判定なし。全体0F不可・合計600F以下。有効な編集は試行リセット。\n時間は両式共通。式の初期化と時間の初期化は別。全てセッション内ドラフト。\n既存の連係条件・入力バッファ・停止式を維持。承認P画像は持続中のみ表示。正式SOへ自動反映しません。",comparisonOptions.transform,12);comparisonOptions.SetActive(false);SyncComparison();
 }
 public void ShowComparisonOptions(bool visible){ShowTrainingOptions(false);if(comparisonOptions==null)return;if(!visible){OptionComparisonVisible=false;comparisonOptions.SetActive(false);return;}ShowInputOptions(false);OptionComparisonVisible=true;foreach(Transform child in optionPanel){bool keep=child.name=="Title"||child.name=="Close"||child.name=="Pause"||child.name.StartsWith("Nav")||child.name=="ComparisonSettings"||child.name=="NavTraining"||child.name=="TrainingSettings";child.gameObject.SetActive(keep);}comparisonOptions.SetActive(true);SyncComparison();LayoutOption(hudWidth,hudHeight);}
 void SyncComparison(){if(combatComparison==null||combatComparison.Active==null)return;syncingComparison=true;for(int row=0;row<3;row++){var command=(TrainingCommand)(row+1);var e=combatComparison.Active.Find(command);float[] values={e.minimumAttack,e.maximumAttack,e.defenseMultiplier,e.threshold,e.guardDamageScale};for(int col=0;col<5;col++)comparisonFields[row*5+col].SetTextWithoutNotify(values[col].ToString("0.###",CultureInfo.InvariantCulture));var t=combatComparison.Timing(command);float[] times={t.startup,t.active,t.recovery};for(int col=0;col<3;col++)comparisonTimingFields[row*3+col].SetTextWithoutNotify(times[col].ToString("0.###",CultureInfo.InvariantCulture));UpdateTimingLabel(row);}syncingComparison=false;comparisonStatus.text=combatComparison.Active.formula+" | "+combatComparison.Status;}
 void UpdateTimingLabel(int row){var t=combatComparison.Timing((TrainingCommand)(row+1));comparisonOptions.transform.Find("CompareTimeLabel"+row).GetComponent<Text>().text=$"発生F / 持続F / 硬直F（持続終了後） | 合計 {t.Total:0.###}F | 判定 [{t.startup:0.###}, {t.startup+t.active:0.###})";}
 void ComparisonEdited(int row){if(syncingComparison)return;var v=new float[5];for(int i=0;i<5;i++)if(!float.TryParse(comparisonFields[row*5+i].text,NumberStyles.Float,CultureInfo.InvariantCulture,out v[i])){comparisonStatus.text="無効な入力: 最後の有効値を維持";return;}if(!combatComparison.Edit((TrainingCommand)(row+1),v[0],v[1],v[2],v[3],v[4])){comparisonStatus.text=combatComparison.Status;return;}comparisonStatus.text=combatComparison.Active.formula+" | "+combatComparison.Status;}
 void ComparisonTimingEdited(int row){if(syncingComparison)return;var v=new float[3];for(int i=0;i<3;i++)if(!float.TryParse(comparisonTimingFields[row*3+i].text,NumberStyles.Float,CultureInfo.InvariantCulture,out v[i])){comparisonStatus.text="時間は数値で入力。最後の有効な時間を維持";return;}combatComparison.EditTiming((TrainingCommand)(row+1),v[0],v[1],v[2]);UpdateTimingLabel(row);comparisonStatus.text=combatComparison.Status;}
 void LayoutComparisonOptions(float w,float h,float left,float x,float right){if(comparisonOptions==null)return;OptionPlace((RectTransform)optionPanel.Find("NavComparison"),18,179,left-24,32);OptionPlace((RectTransform)comparisonOptions.transform,x,55,right,h-95);OptionPlace((RectTransform)comparisonOptions.transform.Find("Header"),0,0,right,24);OptionPlace((RectTransform)comparisonOptions.transform.Find("CompareSubtract"),0,28,right*.42f-5,30);OptionPlace((RectTransform)comparisonOptions.transform.Find("CompareAttenuate"),right*.42f,28,right*.58f,30);for(int row=0;row<3;row++){float y=66+row*106;OptionPlace((RectTransform)comparisonOptions.transform.Find("CompareLabel"+row),0,y,right,20);for(int col=0;col<5;col++)OptionPlace((RectTransform)comparisonFields[row*5+col].transform,col*right/5,y+22,right/5-5,27);OptionPlace((RectTransform)comparisonOptions.transform.Find("CompareTimeLabel"+row),0,y+52,right,20);for(int col=0;col<3;col++)OptionPlace((RectTransform)comparisonTimingFields[row*3+col].transform,col*right/3,y+74,right/3-5,27);}string[] names={"CompareDefaults","CompareTimingDefaults","CompareReset","CompareComboProbe"};for(int i=0;i<4;i++)OptionPlace((RectTransform)comparisonOptions.transform.Find(names[i]),i*right/4,398,right/4-5,30);OptionPlace(comparisonStatus.rectTransform,0,433,right,32);OptionPlace((RectTransform)comparisonOptions.transform.Find("CompareNote"),0,469,right,112);}
